<?php
require 'bootstrap.php';$error='';$id=(int)($_GET['id']??0);
$kinds=['fixed'=>'ลดเป็นจำนวนเงิน','percent'=>'ลดเป็นเปอร์เซ็นต์','shipping'=>'คูปองส่วนลดค่าจัดส่ง / ส่งฟรี','unit_price'=>'ราคาพิเศษต่อชิ้น','flash_price'=>'Flash Sale ราคาพิเศษต่อชิ้น','bundle_price'=>'ซื้อหลายชิ้นราคารวมพิเศษ'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{
    $id=(int)post('id');$name=post('name');$code=strtoupper(post('code'));$kind=post('kind');
    if($name===''||mb_strlen($name)>160||!isset($kinds[$kind])||($code!==''&&!preg_match('/^[A-Z0-9_-]{2,40}$/D',$code)))throw new RuntimeException('กรุณาตรวจชื่อ ประเภท และโค้ดคูปอง');
    if($kind==='shipping'&&$code==='')throw new RuntimeException('ส่วนลดค่าจัดส่งต้องมีโค้ดคูปอง');
    $value=commerce_money_input(post('value')?:'0');$minimum=commerce_money_input(post('min_subtotal')?:'0');$cap=commerce_money_input(post('max_discount')?:'0');
    if($value>4294967295||$minimum>4294967295||$cap>4294967295||($kind==='percent'&&$value>10000)||($kind==='fixed'&&$value<1))throw new RuntimeException('ส่วนลดหรือจำนวนเงินเกินช่วงที่รองรับ');
    $quantity=filter_var(post('min_quantity'),FILTER_VALIDATE_INT);if($quantity===false||$quantity<1||$quantity>10000||($kind==='bundle_price'&&$quantity<2))throw new RuntimeException('จำนวนขั้นต่ำไม่ถูกต้อง');
    $audience=post('audience');if(!in_array($audience,['all','new','returning'],true))throw new RuntimeException('กลุ่มสมาชิกไม่ถูกต้อง');
    $dates=[];foreach(['starts_at','ends_at'] as $field){$date=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',post($field));if(!$date||$date->format('Y-m-d\TH:i')!==post($field))throw new RuntimeException('วันเวลาไม่ถูกต้อง');$dates[$field]=$date->format('Y-m-d H:i:s');}
    if($dates['starts_at']>=$dates['ends_at'])throw new RuntimeException('วันสิ้นสุดต้องอยู่หลังวันเริ่ม');
    $limits=[];foreach(['total_limit','per_user_limit'] as $field){$raw=post($field);if($raw!==''&&(!ctype_digit($raw)||(int)$raw<1||(int)$raw>1000000000))throw new RuntimeException('สิทธิ์ต้องเป็นจำนวนเต็มบวก หรือเว้นว่าง');$limits[$field]=$raw===''?null:(int)$raw;}
    $links=[];foreach(['product_ids'=>'products','category_ids'=>'categories'] as $field=>$table){$raw=$_POST[$field]??[];if(!is_array($raw)||count($raw)>500)throw new RuntimeException('รายการสินค้าหรือหมวดหมู่ไม่ถูกต้อง');$list=[];foreach($raw as $entry){if(!is_string($entry)||!ctype_digit($entry)||(int)$entry<1)throw new RuntimeException('รหัสรายการไม่ถูกต้อง');$list[]=(int)$entry;}$list=array_values(array_unique($list));if($list&&(int)q('SELECT COUNT(*) FROM '.$table.' WHERE id IN ('.implode(',',array_fill(0,count($list),'?')).')',$list)->fetchColumn()!==count($list))throw new RuntimeException('ไม่พบสินค้าหรือหมวดหมู่');$links[$field]=$list;}
    db()->beginTransaction();if($id&&!q('SELECT id FROM promotions WHERE id=? FOR UPDATE',[$id])->fetchColumn())throw new RuntimeException('ไม่พบโปรโมชั่น');
    $params=[$name,$code!==''?$code:null,$kind,$value,$minimum,$cap,$quantity,$audience,$dates['starts_at'],$dates['ends_at'],$limits['total_limit'],$limits['per_user_limit'],isset($_POST['stackable'])?1:0,isset($_POST['active'])?1:0,$admin['id']];
    if($id)q('UPDATE promotions SET name=?,code=?,kind=?,value=?,min_subtotal=?,max_discount=?,min_quantity=?,audience=?,starts_at=?,ends_at=?,total_limit=?,per_user_limit=?,stackable=?,active=?,updated_by=? WHERE id=?',array_merge($params,[$id]));
    else{q('INSERT INTO promotions(name,code,kind,value,min_subtotal,max_discount,min_quantity,audience,starts_at,ends_at,total_limit,per_user_limit,stackable,active,updated_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$params);$id=(int)db()->lastInsertId();}
    q('DELETE FROM promotion_products WHERE promotion_id=?',[$id]);q('DELETE FROM promotion_categories WHERE promotion_id=?',[$id]);
    foreach($links['product_ids'] as $product)q('INSERT INTO promotion_products VALUES (?,?)',[$id,$product]);foreach($links['category_ids'] as $category)q('INSERT INTO promotion_categories VALUES (?,?)',[$id,$category]);
    db()->commit();flash('บันทึกโปรโมชั่นแล้ว สิทธิ์ที่ใช้ไปและคำสั่งซื้อเดิมไม่เปลี่ยน');go('admin/promotions.php?id='.$id);
 }catch(Throwable $exception){if(db()->inTransaction())db()->rollBack();$error=$exception instanceof PDOException?'บันทึกไม่สำเร็จ โค้ดอาจซ้ำหรือข้อมูลไม่ถูกต้อง':$exception->getMessage();}
}
$editing=$id?q('SELECT * FROM promotions WHERE id=?',[$id])->fetch():null;if($id&&!$editing){http_response_code(404);admin_header('ไม่พบโปรโมชั่น');admin_footer();exit;}
$value=static function(string $key,string $default='')use($editing):string {if($_SERVER['REQUEST_METHOD']==='POST')return post($key);if(!$editing)return $default;if(in_array($key,['value','min_subtotal','max_discount'],true))return number_format((int)$editing[$key]/100,2,'.','');if(in_array($key,['starts_at','ends_at'],true))return date('Y-m-d\TH:i',strtotime($editing[$key]));return (string)($editing[$key]??$default);};
$selectedProducts=$id?q('SELECT product_id FROM promotion_products WHERE promotion_id=?',[$id])->fetchAll(PDO::FETCH_COLUMN):[];$selectedCategories=$id?q('SELECT category_id FROM promotion_categories WHERE promotion_id=?',[$id])->fetchAll(PDO::FETCH_COLUMN):[];
if($_SERVER['REQUEST_METHOD']==='POST'){$selectedProducts=is_array($_POST['product_ids']??null)?$_POST['product_ids']:[];$selectedCategories=is_array($_POST['category_ids']??null)?$_POST['category_ids']:[];}
admin_header('โปรโมชั่นและคูปอง');
?>
<p><a href="<?=url('admin/promotions.php')?>">เพิ่มโปรโมชั่นใหม่</a></p><div class="notice">โปรโมชั่นใหม่ไม่เปิดใช้งานจนกว่าจะเลือกเปิดเอง ไม่แก้ราคาต้นฉบับสินค้า ระบบเลือกโปรอัตโนมัติที่ให้ส่วนลดมากที่สุด 1 รายการต่อคำสั่งซื้อ และใช้คูปองได้ไม่เกิน 2 โค้ดเมื่อทุกรายการอนุญาตให้ใช้ร่วม สิทธิ์ถูกจองตอนสร้างคำสั่งซื้อและคืนเมื่อยกเลิก</div>
<?php if($error): ?><p class="error" role="alert"><?=e(t($error))?></p><?php endif ?>
<form method="post" class="panel commerce-admin-form"><?=csrf()?><input type="hidden" name="id" value="<?=$id?>"><?php field('name','ชื่อโปรโมชั่น','text',$value('name'));field('code','โค้ดคูปอง (เว้นว่าง = อัตโนมัติ)','text',$value('code'),false); ?><label>ประเภท<select name="kind"><?php foreach($kinds as $key=>$label): ?><option value="<?=$key?>" <?=$value('kind','fixed')===$key?'selected':''?>><?=e(t($label))?></option><?php endforeach ?></select></label>
<?php field('value','มูลค่า: บาท / เปอร์เซ็นต์ / ราคาต่อชิ้นหรือกลุ่ม (ส่งฟรีใส่ 0)','text',$value('value','0.00'));field('min_subtotal','ยอดซื้อขั้นต่ำก่อนส่วนลด (บาท)','text',$value('min_subtotal','0.00'));field('max_discount','เพดานส่วนลด (บาท, 0 = ไม่จำกัด)','text',$value('max_discount','0.00'));field('min_quantity','จำนวนขั้นต่ำ / จำนวนชิ้นต่อกลุ่ม','number',$value('min_quantity','1')); ?>
<label>กลุ่มสมาชิก<select name="audience"><?php foreach(['all'=>'ทุกคน','new'=>'สมาชิกที่ยังไม่มีคำสั่งซื้อที่ไม่ยกเลิก','returning'=>'สมาชิกที่มีคำสั่งซื้อที่ไม่ยกเลิกแล้ว'] as $key=>$label): ?><option value="<?=$key?>" <?=$value('audience','all')===$key?'selected':''?>><?=e(t($label))?></option><?php endforeach ?></select></label>
<?php field('starts_at','วันเวลาเริ่ม (เวลาไทย)','datetime-local',$value('starts_at',date('Y-m-d\TH:i')));field('ends_at','วันเวลาสิ้นสุด (เวลาไทย)','datetime-local',$value('ends_at',date('Y-m-d\TH:i',strtotime('+7 days'))));field('total_limit','จำนวนสิทธิ์รวม (เว้นว่างไม่จำกัด)','number',$value('total_limit'),false);field('per_user_limit','จำนวนสิทธิ์ต่อสมาชิก (เว้นว่างไม่จำกัด)','number',$value('per_user_limit'),false); ?>
<label>สินค้าที่ร่วม (ไม่เลือก = ทุกสินค้า)<select name="product_ids[]" multiple size="6"><?php foreach(q('SELECT id,name FROM products ORDER BY id') as $product): ?><option value="<?=$product['id']?>" <?=in_array($product['id'],$selectedProducts)?'selected':''?>><?=e($product['name'])?></option><?php endforeach ?></select></label>
<label>หมวดหมู่ที่ร่วม (ไม่เลือก = ทุกหมวด)<select name="category_ids[]" multiple size="6"><?php foreach(q('SELECT id,name FROM categories ORDER BY id') as $category): ?><option value="<?=$category['id']?>" <?=in_array($category['id'],$selectedCategories)?'selected':''?>><?=e($category['name'])?></option><?php endforeach ?></select></label><p class="payment-help">ถ้าเลือกทั้งสินค้าและหมวด ต้องตรงทั้งสองเงื่อนไข ซื้อหลายชิ้นคิดเป็นกลุ่มแยกแต่ละรหัสสินค้า ไม่คละ SKU ส่วนลดคูปองคิดจากยอดสินค้าที่เหลือหลังส่วนลดก่อนหน้า</p>
<label class="checkbox"><input type="checkbox" name="stackable" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['stackable']):!empty($editing['stackable']))?'checked':''?>> อนุญาตใช้ร่วมกับโปรโมชั่น/คูปองอื่น</label><label class="checkbox"><input type="checkbox" name="active" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['active']):!empty($editing['active']))?'checked':''?>> เปิดใช้งาน</label><button>บันทึกโปรโมชั่น</button></form>
<div class="table-wrap"><table><thead><tr><th>ชื่อ / โค้ด</th><th>ช่วงเวลา</th><th>สถานะ</th><th>ใช้สิทธิ์อยู่</th></tr></thead><tbody><?php foreach(q('SELECT p.*,(SELECT COUNT(*) FROM promotion_redemptions r WHERE r.promotion_id=p.id AND r.released_at IS NULL) used FROM promotions p ORDER BY id DESC') as $promotion): ?><tr><td><a href="?id=<?=$promotion['id']?>"><?=e($promotion['name'])?></a><small class="message-email"><?=e($promotion['code']??'อัตโนมัติ')?> · <?=e($kinds[$promotion['kind']])?></small></td><td><?=e($promotion['starts_at'])?><br><?=e($promotion['ends_at'])?></td><td><?=$promotion['active']?'เปิด':'ปิด'?></td><td><?=$promotion['used']?> / <?=e($promotion['total_limit']??'ไม่จำกัด')?></td></tr><?php endforeach ?></tbody></table></div>
<?php admin_footer(); ?>
